module MUX_8x3 (
    input [7:0] in,
    input [7:0] shift,
    input [2:0] out,
    output [7:0] val_3
);

    wire [7:0] w0;
    wire [7:0] w1;
    wire [7:0] w2;

    assign w0 = (out == 3'b000) ? in : 8'h00;
    assign w1 = (out == 3'b001) ? in : 8'h00;
    assign w2 = (out == 3'b010) ? in : 8'h00;

    assign w1 = (out == 3'b011) ? shift : 8'h00;
    assign w2 = (out == 3'b100) ? shift : 8'h00;

    assign val_3 = w0 | w1 | w2;

endmodule

