module adder(
    input wire [7:0] a, 
    input wire [7:0] b, 
    input wire carry_in,
    output wire [7:0] sum, 
    output wire carry_out
);

assign sum = a + b + carry_in;
assign carry_out = carry_in | (a & b);

endmodule

module core (
    input wire [6:0] opcode,    // 7-bit Opcode input
    input wire [7:0] a,         // 8-bit Register A input
    input wire [7:0] b,         // 8-bit Register B input
    output reg [7:0] data_1,    // 8-bit Data output
    output reg [7:0] data_2     // 8-bit Data output
);
    always @(*) begin
        if (opcode == 7'b0000000) begin
            data_1 = a;
            data_2 = b;
        end else if (opcode == 7'b0000001) begin
            data_1 = 8'b00000000;
            data_2 = a + b;
        end else if (opcode == 7'b0000010) begin
            data_1 = a | b;
            data_2 = a & b;
        end else if (opcode == 7'b0000011) begin
            data_1 = a;
            data_2 = 8'b00000000;
        end else if (opcode == 7'b0000100) begin
            data_1 = a + 8'b00000001;
            data_2 = a - 8'b00000001;
        end else begin
            data_1 = 8'b00000000;
            data_2 = 8'b00000000;
        end
    end
endmodule

module ROM (
    input wire [7:0] addr,        // 8-bit Address input
    output reg [15:0] dout        // 16-bit Data output
);
    always @(*) begin
        case (addr)
            8'h00: dout = 16'h0000;
            8'h01: dout = 16'h0001;
            8'h02: dout = 16'h4321;
            8'h03: dout = 16'h1234;
            default: dout = 16'h0000;
        endcase
    end
endmodule

